async function refreshStatus(){try{const t=await Promethe.api("status.json");if(!t.ok)throw new Error("status failed");const n=await t.json();document.getElementById("statVersion").textContent=n.version||"--";document.getElementById("statModchip").textContent=n.modchip||"--";document.getElementById("statSkin").textContent=n.skin||"--";document.getElementById("statCpuTemp").textContent=n.cpuTemp!=null?n.cpuTemp+" C":"--";document.getElementById("statMbTemp").textContent=n.mbTemp!=null?n.mbTemp+" C":"--";document.getElementById("statFan").textContent=n.fanSpeed!=null?n.fanSpeed+"%":"--";document.getElementById("statMem").textContent=n.freeMemKb!=null?Math.round(n.freeMemKb/1024)+" MB":"--";document.getElementById("statSpeed").textContent=n.cpuMhz!=null&&n.gpuMhz!=null?n.cpuMhz+" / "+n.gpuMhz+" MHz":"--";document.getElementById("statAutoBoot").textContent=n.autoBoot||"None";document.getElementById("statAvRes").textContent=n.avRes||"--"}catch(n){document.getElementById("statVersion").textContent="Offline"}}async function waitForScreenshotReady(){for(;;){const n=await Promethe.api("screenshotready.json");if(!n.ok)throw new Error("Failed to check screenshot status.");const t=await n.json();if(t.ready)return;await new Promise(function(n){window.setTimeout(n,100)})}}async function takeScreenshot(){try{Promethe.toast("Capturing screenshot...");await Promethe.api("takescreenshot");await waitForScreenshotReady();const t=await Promethe.api("downloadscreenshot"),i=await t.blob(),r=window.URL.createObjectURL(i),n=document.createElement("a");n.href=r;n.download="screenshot.png";document.body.appendChild(n);n.click();n.remove();Promethe.toast("Screenshot saved.","success")}catch(n){Promethe.toast("Screenshot failed.","error")}}async function rebootConsole(){try{await Promethe.rebootAndWait();refreshStatus()}catch(n){Promethe.toast("Reboot timed out.","error")}}async function shutdownConsole(){try{await Promethe.shutdownConsole()}catch(n){Promethe.toast("Shutdown failed.","error")}}let statusTimer=null;window.onload=function(){document.getElementById("year").textContent=(new Date).getFullYear();refreshStatus();statusTimer=window.setInterval(refreshStatus,5e3)};